use soroban_sdk::{contract, contractimpl, contracttype, Address, Env, Vec};

#[contracttype]
pub enum DataKey {
    Count,
}

#[contract]
pub struct Registry;

#[contractimpl]
impl Registry {
    // The count is the caller's to choose: a long enough list makes this call
    // exceed the invocation budget and trap.
    pub fn total(env: Env, members: Vec<Address>) -> i128 {
        let mut sum = 0i128;
        for member in members.iter() {
            let balance: i128 = env
                .storage()
                .persistent()
                .get(&member)
                .unwrap_or(0);
            sum = sum + balance;
        }
        sum
    }

    // The count comes from storage, so nobody looking at the call can see how long
    // it is, and it grows with use.
    pub fn settle(env: Env) {
        let count: u32 = env
            .storage()
            .instance()
            .get(&DataKey::Count)
            .unwrap_or(0);
        for i in 0..count {
            env.storage().persistent().get(&i);
        }
    }
}

