use soroban_sdk::{contract, contractimpl, contracttype, Address, Env, Vec};

#[contracttype]
pub enum DataKey {
    Count,
}

#[contract]
pub struct Registry;

#[contractimpl]
impl Registry {
    // A literal bound is a bound: the work per call is fixed and known.
    pub fn settle(env: Env) {
        for i in 0..16 {
            env.storage().persistent().get(&i);
        }
    }

    // Iterating a caller-supplied list is fine when the body touches no storage:
    // the iteration is arithmetic in registers, not ledger entries.
    pub fn count_members(env: Env, members: Vec<Address>) -> u32 {
        let mut total = 0u32;
        for member in members.iter() {
            let _ = member;
            total = total + 1;
        }
        env.storage().instance().set(&DataKey::Count, &total);
        total
    }
}
